DROP INDEX `idx_word_stats_promising`;--> statement-breakpoint
CREATE INDEX `idx_word_stats_promising` ON `word_stats` ("score" DESC) WHERE "word_stats"."likes" > 0 AND ("word_stats"."likes" + "word_stats"."dislikes" < 5 OR "word_stats"."score" < 0.55) AND ("word_stats"."likes" + "word_stats"."dislikes" < 15 OR "word_stats"."score" >= 0.5);